def R(a,b,n=1):
    global s; assert s.count(a)==n,(s.count(a),a[:90]); s=s.replace(a,b)
def val_end(i):
    """i 指向值的第一個字元；回傳值結束後的位置"""
    while s[i] in ' \n': i+=1
    c=s[i]
    if c in "'\"`":
        q=c; i+=1
        while s[i]!=q:
            if s[i]=='\\': i+=1
            i+=1
        return i+1
    d=0
    while True:
        c=s[i]
        if c in '{[(': d+=1
        elif c in '}])':
            d-=1
            if d==0: return i+1
        elif c in "'\"`":
            q=c; i+=1
            while s[i]!=q:
                if s[i]=='\\': i+=1
                i+=1
        i+=1
def ins_after_key(marker,key,text):
    global s
    t=s.index(marker); import re
    m=re.compile(r"[\s{,]"+key+r"\s*:").search(s,t)
    assert m and m.start()-t<200000,(marker,key)
    e=val_end(m.end())
    s=s[:e]+',\n '+text+s[e:]
def ins_after_line(marker,needle,text):
    global s
    t=s.index(marker); i=s.index(needle,t); e=s.index('\n',i)
    s=s[:e]+'\n '+text+s[e:]

